//! pg_walsummary CLI tests: output pinned against golden files generated by
//! the stock C pg_walsummary (PostgreSQL 18) run on the same summary file
//! (testdata/README for regeneration). The fixture itself is written by our
//! blkreftable writer — byte-identical to what the WAL summarizer persists
//! (native-endian; the goldens were generated on a little-endian host, like
//! every supported target).

use std::path::PathBuf;
use std::process::Command;

use types_core::ForkNumber;
use types_storage::RelFileLocator;

fn testdata(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("testdata").join(name)
}

fn bin() -> &'static str {
    env!("CARGO_BIN_EXE_pg_walsummary")
}

fn rl(spc: u32, db: u32, rel: u32) -> RelFileLocator {
    RelFileLocator { spcOid: spc, dbOid: db, relNumber: rel }
}

/// The committed fixture's contents, rebuilt from scratch. Exercises: a
/// limit-block line, out-of-order array-chunk blocks (sorted by the tool),
/// a contiguous run collapsing to a range, an isolated block, a non-main
/// fork, a second relation, and a bitmap chunk (4096 marks in one chunk).
fn build_sample_summary() -> Vec<u8> {
    let cx = mcx::MemoryContext::new("fixture");
    let mcx = cx.mcx();
    let mut tab = blkreftable::BlockRefTable::new(mcx);

    // rel 16384 MAIN: out-of-order marks + a contiguous run + an outlier.
    for b in [7u32, 3, 4, 5, 900] {
        tab.mark_block_modified(rl(1663, 5, 16384), ForkNumber::MAIN_FORKNUM, b).unwrap();
    }
    // rel 16384 VM: single block, plus a limit block.
    tab.mark_block_modified(rl(1663, 5, 16384), ForkNumber::VISIBILITYMAP_FORKNUM, 0).unwrap();
    tab.set_limit_block(rl(1663, 5, 16384), ForkNumber::VISIBILITYMAP_FORKNUM, 2);
    // rel 16385 MAIN: a full bitmap chunk (blocks 0..=4095).
    for b in 0u32..4096 {
        tab.mark_block_modified(rl(1663, 5, 16385), ForkNumber::MAIN_FORKNUM, b).unwrap();
    }
    // rel 16386 INIT in another database: limit block only, no blocks.
    tab.set_limit_block(rl(1664, 0, 16386), ForkNumber::INIT_FORKNUM, 0);

    let mut bytes = Vec::new();
    tab.write(|chunk: &[u8]| {
        bytes.extend_from_slice(chunk);
        Ok(())
    })
    .unwrap();
    bytes
}

/// The committed fixture is exactly what our writer emits today — pins the
/// on-disk format the goldens were generated from.
#[test]
fn fixture_matches_writer_output() {
    let expected = std::fs::read(testdata("sample.summary")).unwrap();
    assert_eq!(build_sample_summary(), expected, "fixture drifted; regenerate goldens");
}

fn run(args: &[&str]) -> (String, String, i32) {
    let out = Command::new(bin()).args(args).output().unwrap();
    (
        String::from_utf8(out.stdout).unwrap(),
        String::from_utf8(out.stderr).unwrap(),
        out.status.code().unwrap(),
    )
}

fn golden(name: &str) -> String {
    String::from_utf8(std::fs::read(testdata(name)).unwrap()).unwrap()
}

#[test]
fn default_output_matches_c() {
    let f = testdata("sample.summary");
    let (stdout, stderr, code) = run(&[f.to_str().unwrap()]);
    assert_eq!(code, 0, "{stderr}");
    assert_eq!(stderr, "");
    assert_eq!(stdout, golden("golden-default.out"));
}

#[test]
fn individual_output_matches_c() {
    let f = testdata("sample.summary");
    let (stdout, stderr, code) = run(&["--individual", f.to_str().unwrap()]);
    assert_eq!(code, 0, "{stderr}");
    assert_eq!(stdout, golden("golden-individual.out"));
    // -i is the same option.
    let (short, _, _) = run(&["-i", f.to_str().unwrap()]);
    assert_eq!(short, stdout);
}

/// C's --quiet suppresses only the block/range lines: the limit-block line
/// prints before the quiet check in dump_one_relation. Golden from the C
/// tool run with -q on the same fixture.
#[test]
fn quiet_still_prints_limit_lines_like_c() {
    let f = testdata("sample.summary");
    let (stdout, stderr, code) = run(&["-q", f.to_str().unwrap()]);
    assert_eq!(code, 0, "{stderr}");
    assert_eq!(stderr, "");
    assert_eq!(stdout, golden("golden-quiet.out"));
    // --quiet is the same option.
    let (long, _, _) = run(&["--quiet", f.to_str().unwrap()]);
    assert_eq!(long, stdout);
}

#[test]
fn multiple_files_concatenate() {
    let f = testdata("sample.summary");
    let one = run(&[f.to_str().unwrap()]).0;
    let two = run(&[f.to_str().unwrap(), f.to_str().unwrap()]).0;
    assert_eq!(two, format!("{one}{one}"));
}

#[test]
fn no_input_files_is_c_error() {
    let (stdout, stderr, code) = run(&[]);
    assert_eq!(code, 1);
    assert_eq!(stdout, "");
    assert_eq!(
        stderr,
        "pg_walsummary: error: no input files specified\n\
         pg_walsummary: hint: Try \"pg_walsummary --help\" for more information.\n"
    );
}

#[test]
fn missing_file_is_c_open_error() {
    let (stdout, stderr, code) = run(&["/nonexistent/nope.summary"]);
    assert_eq!(code, 1);
    assert_eq!(stdout, "");
    assert!(
        stderr.starts_with("pg_walsummary: error: could not open file \"/nonexistent/nope.summary\":"),
        "{stderr}"
    );
}

#[test]
fn garbage_file_is_c_magic_error() {
    let dir = std::env::temp_dir().join(format!("pg_walsummary_test_{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("bad.summary");
    std::fs::write(&path, [0x11u8, 0x22, 0x33, 0x44, 0, 0, 0, 0]).unwrap();
    let (stdout, stderr, code) = run(&[path.to_str().unwrap()]);
    std::fs::remove_dir_all(&dir).ok();
    assert_eq!(code, 1);
    assert_eq!(stdout, "");
    assert!(
        stderr.starts_with(&format!(
            "pg_walsummary: error: file \"{}\" has wrong magic number: expected 1697321851, found ",
            path.display()
        )),
        "{stderr}"
    );
}

#[test]
fn truncated_file_ends_unexpectedly() {
    let full = std::fs::read(testdata("sample.summary")).unwrap();
    let dir = std::env::temp_dir().join(format!("pg_walsummary_trunc_{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("trunc.summary");
    std::fs::write(&path, &full[..full.len() / 2]).unwrap();
    let (_, stderr, code) = run(&[path.to_str().unwrap()]);
    std::fs::remove_dir_all(&dir).ok();
    assert_eq!(code, 1);
    assert!(
        stderr.contains("ends unexpectedly") || stderr.contains("wrong checksum"),
        "{stderr}"
    );
}

#[test]
fn help_and_version() {
    let (stdout, _, code) = run(&["--help"]);
    assert_eq!(code, 0);
    assert!(stdout.contains("prints the contents of a WAL summary file"));
    assert!(stdout.contains("-i, --individual"));
    assert!(stdout.contains("-q, --quiet"));
    let (v, _, code) = run(&["--version"]);
    assert_eq!(code, 0);
    assert!(v.starts_with("pg_walsummary (PostgreSQL) "), "{v}");
}

#[test]
fn bad_option_is_c_getopt_error() {
    let (_, stderr, code) = run(&["-x", "whatever"]);
    assert_eq!(code, 1);
    assert_eq!(
        stderr,
        "pg_walsummary: invalid option -- 'x'\n\
         pg_walsummary: hint: Try \"pg_walsummary --help\" for more information.\n"
    );
}

/// Used once to (re)generate testdata/sample.summary; kept runnable so the
/// regeneration recipe in testdata/README stays true.
#[test]
#[ignore = "generator: writes testdata/sample.summary"]
fn generate_fixture() {
    std::fs::write(testdata("sample.summary"), build_sample_summary()).unwrap();
}
